<?php if ($saveError): ?><div class="cx-alert cx-alert-error" role="alert"><?php echo authEscape($saveError); ?></div><?php endif; ?>
<?php if (isset($_GET['saved'])): ?><div class="cx-alert" role="status">Product saved. The storefront now uses the updated price and availability.</div><?php endif; ?>
<?php if (isset($_GET['created'])): ?><div class="cx-alert" role="status">Product added. It is now visible in your storefront.</div><?php endif; ?>
<?php if ($isCreating || $editingProduct):
    if ($isCreating) $editingProduct = ['id'=>0,'price_per_pallet'=>0,'inventory'=>null,'min_order'=>1,'status'=>'in-stock','warehouse'=>'To be confirmed'];
    $value = fn($key, $fallback = '') => authEscape($_SERVER['REQUEST_METHOD'] === 'POST' ? requestText($_POST,$key) : (string)$fallback);
?>
<section id="product-editor" class="cx-panel" style="margin-bottom:28px;scroll-margin-top:120px"><div class="cx-panel-head"><h2><?php echo $isCreating ? 'Add a new product' : 'Edit ' . authEscape($editingProduct['name']); ?></h2><a class="cx-link" href="<?php echo siteUrl('admin-products.php'); ?>">Cancel</a></div>
    <form method="post" enctype="multipart/form-data" action="<?php echo siteUrl('admin-products.php' . ($isCreating ? '?action=create' : '?edit=' . $editingProduct['id'])); ?>" class="cx-stack"><input type="hidden" name="csrf_token" value="<?php echo authEscape($_SESSION['csrf_token']); ?>"><input type="hidden" name="action" value="<?php echo $isCreating ? 'create' : 'update'; ?>"><input type="hidden" name="product_id" value="<?php echo $editingProduct['id']; ?>"><div class="cx-form-grid">
        <?php if ($isCreating): ?>
        <div class="cx-field"><label for="product-name">Product name</label><input id="product-name" name="name" maxlength="180" value="<?php echo $value('name'); ?>" required></div>
        <div class="cx-field"><label for="sku">SKU</label><input id="sku" name="sku" maxlength="80" pattern="[A-Za-z0-9][A-Za-z0-9\-]*" value="<?php echo $value('sku'); ?>" required><small>Unique code using letters, numbers, and hyphens.</small></div>
        <div class="cx-field"><label for="category">Category</label><input id="category" name="category" maxlength="80" placeholder="Purified Water" value="<?php echo $value('category'); ?>" required></div>
        <div class="cx-field"><label for="pallet-type">Pallet size</label><select id="pallet-type" name="pallet_type"><?php foreach (['Full pallet','Half pallet'] as $type): ?><option value="<?php echo $type; ?>" <?php echo $value('pallet_type','Full pallet') === $type ? 'selected' : ''; ?>><?php echo $type; ?></option><?php endforeach; ?></select></div>
        <div class="cx-field"><label for="bottle-size">Bottle size</label><input id="bottle-size" name="bottle_size" maxlength="80" placeholder="16.9 oz" value="<?php echo $value('bottle_size'); ?>" required></div>
        <div class="cx-field"><label for="bottles-per-case">Bottles per case</label><input id="bottles-per-case" name="bottles_per_case" type="number" min="1" max="9999" value="<?php echo $value('bottles_per_case'); ?>" required></div>
        <div class="cx-field"><label for="cases-per-pallet">Cases per pallet</label><input id="cases-per-pallet" name="cases_per_pallet" type="number" min="1" max="9999" value="<?php echo $value('cases_per_pallet'); ?>" required><small>Total bottles per pallet is calculated automatically.</small></div>
        <div class="cx-field"><label for="pallet-weight">Pallet weight (optional)</label><input id="pallet-weight" name="pallet_weight" maxlength="100" placeholder="To be confirmed" value="<?php echo $value('pallet_weight'); ?>"></div>
        <div class="cx-field"><label for="pallet-dimensions">Pallet dimensions (optional)</label><input id="pallet-dimensions" name="pallet_dimensions" maxlength="100" placeholder="To be confirmed" value="<?php echo $value('pallet_dimensions'); ?>"></div>
        <div class="cx-field cx-field-wide"><label for="product-image">Upload product image</label><input id="product-image" name="product_image" type="file" accept="image/jpeg,image/png,image/webp,image/gif" aria-describedby="product-image-help"><small id="product-image-help">Choose a JPG, PNG, WebP, or GIF from your computer (up to 2 MB). The image is uploaded when you add the product.</small><?php if ($saveError): ?><small>Please choose your file again before submitting.</small><?php endif; ?></div>
        <div class="cx-field cx-field-wide"><label for="image">Or use an image URL or existing path</label><input id="image" name="image" maxlength="500" placeholder="https://example.com/product.jpg" value="<?php echo $value('image'); ?>"><small>Optional when uploading a file. An uploaded image takes priority. Existing paths are relative to assets, such as images/products/1.jpg.</small></div>
        <div class="cx-field cx-field-wide"><label for="description">Description</label><textarea id="description" name="description" rows="4" maxlength="10000" required><?php echo $value('description'); ?></textarea></div>
        <div class="cx-field cx-field-wide"><label for="features">Features (optional)</label><textarea id="features" name="features" rows="3" maxlength="10000" placeholder="One feature per line"><?php echo $value('features'); ?></textarea></div>
        <?php endif; ?>
        <div class="cx-field"><label for="price">Price per pallet (USD)</label><input id="price" name="price" type="number" min="0.01" max="9999999.99" step="0.01" value="<?php echo $value('price',$isCreating ? '' : number_format($editingProduct['price_per_pallet'],2,'.','')); ?>" required></div>
        <div class="cx-field"><label for="inventory">Available pallets</label><input id="inventory" name="inventory" type="number" min="0" max="9999999" value="<?php echo $value('inventory',$editingProduct['inventory'] ?? ''); ?>"><small>Leave blank when stock is unconfirmed. Confirmed counts are reserved when an order is placed.</small></div>
        <div class="cx-field"><label for="min-order">Minimum pallets per order</label><input id="min-order" name="min_order" type="number" min="1" max="999" value="<?php echo $value('min_order',$editingProduct['min_order']); ?>" required></div>
        <div class="cx-field"><label for="stock-status">Availability</label><select id="stock-status" name="status"><?php foreach (['in-stock'=>'In stock','out-of-stock'=>'Out of stock'] as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $value('status',$editingProduct['status']) === $key ? 'selected' : ''; ?>><?php echo $label; ?></option><?php endforeach; ?></select></div>
        <div class="cx-field cx-field-wide"><label for="warehouse">Warehouse</label><input id="warehouse" name="warehouse" maxlength="160" value="<?php echo $value('warehouse',$editingProduct['warehouse']); ?>" required></div>
    </div><button class="lp-button lp-button-primary" type="submit"><?php echo $isCreating ? 'Add product' : 'Save product'; ?> &rarr;</button></form>
</section>
<?php endif; ?>
